// Merge all fetched data into a single context object
const trendsMorocco = $('Google Trends Morocco').first().json;
const platformStats = $('Udarsy Platform Stats').first().json;
const calendarEvents = $('Upcoming Calendar Events').first().json;

// Parse Google Trends (the API returns JSONP-like response)
let moroccoTrends = [];

try {
  const maText = typeof trendsMorocco === 'string' ? trendsMorocco : (trendsMorocco.data || JSON.stringify(trendsMorocco));
  const maClean = maText.replace(/^\)\]\}',?\n?/, '');
  const maJson = JSON.parse(maClean);
  moroccoTrends = maJson.default?.trendingSearchesDays?.[0]?.trendingSearches?.map(t => t.title?.query || t.query) || [];
} catch (e) {
  moroccoTrends = ['(trends fetch failed)'];
}

// Extract useful stats
const stats = platformStats.data || platformStats;
const events = Array.isArray(calendarEvents.data || calendarEvents)
  ? (calendarEvents.data || calendarEvents)
  : [];

// Get upcoming events for next 2 weeks
const twoWeeksOut = new Date(Date.now() + 14 * 24 * 60 * 60 * 1000);
const upcomingEvents = events
  .filter(e => new Date(e.date || e.startDate) <= twoWeeksOut)
  .slice(0, 10)
  .map(e => ({ title: e.title, date: e.date || e.startDate, type: e.type || e.category }));

// Current week info
const now = new Date();
const weekStart = new Date(now);
weekStart.setDate(now.getDate() - now.getDay() + 1);

return [{
  json: {
    week_start: weekStart.toISOString().split('T')[0],
    current_month: now.toLocaleString('en', { month: 'long' }),
    morocco_trending: moroccoTrends.slice(0, 10),
    platform_stats: {
      total_users: stats.totalUsers || stats.users || 'N/A',
      total_lessons: stats.totalLessons || stats.lessons || 'N/A',
      total_subjects: stats.totalSubjects || stats.subjects || 'N/A',
      active_users_today: stats.activeToday || 'N/A',
      popular_subjects: stats.popularSubjects || stats.topSubjects || []
    },
    upcoming_events: upcomingEvents,
    moroccan_academic_context: {
      note: 'BAC exams in June, Brevet in May, university registration in Sept, school starts in Sept, winter break in Dec, spring break in March/April, Ramadan varies yearly'
    }
  }
}];

// Parse GPT calendar response and prepare for Sheets + Telegram
const raw = $input.first().json;
let calendar;
try {
  const text = raw.message?.content || raw.text || JSON.stringify(raw);
  const jsonMatch = text.match(/```json\n?([\s\S]*?)\n?```/) || text.match(/\{[\s\S]*\}/);
  calendar = JSON.parse(jsonMatch ? (jsonMatch[1] || jsonMatch[0]) : text);
} catch (e) {
  return [{ json: { error: 'Failed to parse calendar', raw: raw, parseError: e.message } }];
}

// Flatten daily posts for Google Sheets
const rows = [];

calendar.daily_plan?.forEach(day => {
  day.posts?.forEach(post => {
    rows.push({
      week_of: calendar.week_of,
      day: day.day,
      date: day.date,
      day_theme: day.theme,
      platform: post.platform,
      time: post.time,
      post_type: post.type,
      content: post.content,
      hashtags: (post.hashtags || []).join(' '),
      media_needed: post.media_needed || '',
      cta: post.cta || '',
      notes: post.notes || '',
      status: 'planned',
      created_at: new Date().toISOString()
    });
  });
});

// Add LinkedIn posts
calendar.linkedin_posts?.forEach(post => {
  rows.push({
    week_of: calendar.week_of,
    day: post.day,
    date: '',
    day_theme: post.type,
    platform: 'LinkedIn',
    time: '9:00 AM CET',
    post_type: post.type,
    content: post.content,
    hashtags: '',
    media_needed: '',
    cta: '',
    notes: '',
    status: 'planned',
    created_at: new Date().toISOString()
  });
});

// Add TikTok/Reels
calendar.tiktok_reels?.forEach(reel => {
  rows.push({
    week_of: calendar.week_of,
    day: reel.day,
    date: '',
    day_theme: reel.concept,
    platform: 'TikTok/Reels',
    time: '8:00 PM CET',
    post_type: 'reel',
    content: `HOOK: ${reel.hook}\n\n${reel.script_outline}`,
    hashtags: '',
    media_needed: `Video ${reel.duration} - ${reel.trending_angle}`,
    cta: '',
    notes: reel.trending_angle || '',
    status: 'planned',
    created_at: new Date().toISOString()
  });
});

// Add Email newsletters
calendar.email_newsletters?.forEach(email => {
  const sections = (email.sections || []).map(s => `${s.title}: ${s.content_brief}`).join('\n');
  rows.push({
    week_of: calendar.week_of,
    day: email.send_day,
    date: '',
    day_theme: 'Newsletter',
    platform: 'Email',
    time: '7:00 AM CET',
    post_type: 'newsletter',
    content: `Subject: ${email.subject}\nPreview: ${email.preview}\n\n${sections}`,
    hashtags: '',
    media_needed: '',
    cta: '',
    notes: '',
    status: 'planned',
    created_at: new Date().toISOString()
  });
});

// Store full calendar JSON in first row for reference
if (rows.length > 0) {
  rows[0]._fullCalendar = calendar;
}

return rows.map(row => ({ json: row }));

// Build Telegram summary of the weekly calendar
const items = $input.all();
const firstItem = items[0]?.json || {};
const calendar = firstItem._fullCalendar || {};

const platformCounts = {};
items.forEach(item => {
  const p = item.json.platform || 'Unknown';
  platformCounts[p] = (platformCounts[p] || 0) + 1;
});

const countSummary = Object.entries(platformCounts)
  .map(([p, c]) => `  - ${p}: ${c} post(s)`)
  .join('\n');

let msg = `📅 *Udarsy Weekly Content Calendar*\n`;
msg += `📆 Week of: ${calendar.week_of || 'N/A'}\n`;
msg += `🎯 Theme: ${calendar.theme_of_the_week || 'N/A'}\n\n`;
msg += `📊 *Total planned: ${items.length} pieces*\n${countSummary}\n\n`;

// Show daily overview
if (calendar.daily_plan) {
  msg += `📋 *Daily Overview:*\n`;
  calendar.daily_plan.forEach(day => {
    msg += `  *${day.day}* (${day.date || ''}): ${day.theme}\n`;
    msg += `    ${day.posts?.length || 0} posts planned\n`;
  });
  msg += '\n';
}

if (calendar.notes) {
  msg += `📝 *Notes:* ${calendar.notes}\n\n`;
}

msg += `✅ Full calendar saved to Google Sheets.\n`;
msg += `👉 Review and approve each post before publishing.`;

return [{ json: { message: msg } }];

// Gets chatId from Telegram command center webhook, or falls back to env var
const fromWebhook = $input.first().json.body?.chatId;
const chatId = fromWebhook || $env.TELEGRAM_CHAT_ID;
return [{ json: { chatId } }];
